use model::{ClassDef, API_VERSION, CLASSES, CRATE_VERSION, MODEL_VERSION, PRODUCT};
use serde_json::{json, Value};
use std::io::Read;
use store::Engine as _;
use store::RowStore;

fn envelope(class: &ClassDef, path: &str, data: Value) -> Value {
    json!({
        "apiVersion": API_VERSION,
        "product": PRODUCT,
        "productVersion": CRATE_VERSION,
        "modelVersion": MODEL_VERSION,
        "kind": class.name,
        "self": path,
        "servedFrom": class.graph,
        "data": data,
    })
}

/// #4744 — the product root: every field a domain puts on the header (c:inHeader), per
/// collection, from the rows the caller may see. No class marks a field → no root route.
pub fn header(store: &dyn RowStore, viewer: Option<&str>) -> (u16, Value) {
    let mut data = serde_json::Map::new();
    for c in CLASSES {
        let fields: Vec<&str> = c.fields.iter().filter(|f| f.header).map(|f| f.name).collect();
        if fields.is_empty() {
            continue;
        }
        // a glance: the newest rows when the model names the field that orders them (c:headerNewest)
        // and only the rows the model names for it (c:headerOnly, e.g. the cards in WIP)
        let w = store::Where {
            eq: c.fields.iter().filter_map(|f| f.header_only.map(|v| (f.name.to_string(), v.to_string()))).collect(),
            sort: c.fields.iter().find(|f| f.newest).map(|f| (f.name.to_string(), true)),
            ..Default::default()
        };
        let page = if w == store::Where::default() {
            match viewer { Some(v) => store.list_seen_by(c, 100, 0, v), None => store.list(c, 100, 0) }
        } else {
            store.list_where(c, 100, 0, viewer, &w)
        };
        let rows = match page { Ok((rows, _)) => rows, Err(m) => return error(503, "store", &m) };
        let rows: Vec<Value> = rows.into_iter().map(|r| {
            let mut o = serde_json::Map::new();
            o.insert("name".into(), r.get("name").cloned().unwrap_or(Value::Null));
            for f in &fields {
                o.insert((*f).into(), r.get(*f).cloned().unwrap_or(Value::Null));
            }
            Value::Object(o)
        }).collect();
        // #4744 AC8 — each header line opens its domain's stream, where the same filter and search apply
        let stream = format!("/{PRODUCT}/{}/{}", c.domain, c.segment);
        data.insert(format!("{}.{}", c.domain, c.segment), json!({ "fields": fields, "rows": rows, "stream": stream }));
    }
    if data.is_empty() {
        return error(404, "unknown-route", "no domain of this product puts a field on its header");
    }
    (200, json!({
        "apiVersion": API_VERSION,
        "product": PRODUCT,
        "productVersion": CRATE_VERSION,
        "modelVersion": MODEL_VERSION,
        "kind": "Header",
        "self": format!("/{PRODUCT}"),
        "data": data,
    }))
}

fn error(code: u16, kind: &str, message: &str) -> (u16, Value) {
    (code, json!({ "error": kind, "message": message }))
}

/// #4744 — `%XX` and `+` in a query value, decoded; a malformed escape is kept as typed.
fn decode(v: &str) -> String {
    let b = v.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'+' => out.push(b' '),
            b'%' if i + 2 < b.len() => match std::str::from_utf8(&b[i + 1..i + 3]).ok().and_then(|h| u8::from_str_radix(h, 16).ok()) {
                Some(x) => { out.push(x); i += 2; }
                None => out.push(b'%'),
            },
            c => out.push(c),
        }
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// #4744 AC8 — the filter a collection read carries: every query key but limit and offset
/// names a field of the class (or is `q`, the text search). An unknown key is refused by name.
fn where_of(class: &ClassDef, query: &str) -> Result<store::Where, (u16, Value)> {
    let mut w = store::Where::default();
    for kv in query.split('&').filter(|kv| !kv.is_empty()) {
        let (k, v) = kv.split_once('=').unwrap_or((kv, ""));
        let (k, v) = (decode(k), decode(v));
        let known = |f: &str| f == "label" || f == "status" || class.fields.iter().any(|d| d.name == f);
        let unknown = |f: &str| error(400, "unknown-field", &format!("{} has no field '{f}'", class.name));
        if let Some((f, op)) = k.strip_suffix(".lt").map(|f| (f, "<")).or_else(|| k.strip_suffix(".gt").map(|f| (f, ">"))) {
            if !known(f) { return Err(unknown(f)); }
            // a bound compares text, which orders ISO times and plain text, never numbers (Kade's review)
            let datatype = class.fields.iter().find(|d| d.name == f).map_or("string", |d| d.datatype);
            if !matches!(datatype, "string" | "dateTime" | "date") {
                return Err(error(400, "unordered-field", &format!("{}.{f} is {datatype}: a bound needs a text or time field", class.name)));
            }
            w.bounds.push((f.to_string(), op, v));
            continue;
        }
        match k.as_str() {
            "limit" | "offset" => {}
            "sort" => {
                let (f, desc) = v.strip_prefix('-').map(|f| (f, true)).unwrap_or((v.as_str(), false));
                if !known(f) { return Err(unknown(f)); }
                w.sort = Some((f.to_string(), desc));
            }
            "q" => w.q = Some(v),
            f if f == "label" || f == "status" || class.fields.iter().any(|d| d.name == f) => w.eq.push((k.clone(), v)),
            f => return Err(error(400, "unknown-field", &format!("{} has no field '{f}'", class.name))),
        }
    }
    Ok(w)
}

fn query_param(query: &str, key: &str) -> Option<usize> {
    query.split('&').find_map(|kv| kv.strip_prefix(&format!("{key}=")).and_then(|v| v.parse().ok()))
}

pub struct Ctx<'a> {
    pub store: &'a dyn RowStore,
    pub who: &'a auth::Auth,
    pub events: String,
    /// #4524 — `reads.public`: true lets anyone read; false (the default) filters every read to its caller
    pub reads_public: bool,
}

fn refused(r: rules::Refusal) -> (u16, Value) {
    error(r.code, r.kind, &r.message)
}

/// A write, after the caller is known: shape check → owner or Permission → keep the
/// displaced version → one atomic store write → event. Nothing is written on a refusal.
pub fn write(ctx: &Ctx, caller: &auth::Caller, method: &str, class: &ClassDef, name: Option<&str>, body: &str) -> (u16, Value) {
    // #4742 — a composed domain belongs to another product: this one reads it, its owner writes it
    if class.composed {
        return error(405, "composed", &format!("{} is composed here from its owner; write it through {}'s own door", class.domain, class.domain));
    }
    let parsed: Value = if body.trim().is_empty() && method == "DELETE" { json!({}) } else {
        match serde_json::from_str(body) { Ok(v) => v, Err(e) => return error(400, "bad-json", &e.to_string()) }
    };
    let Some(obj) = parsed.as_object() else { return error(400, "bad-json", "the body must be a JSON object") };
    let name = match (method, name) {
        ("POST", None) => match obj.get("name").and_then(Value::as_str) {
            Some(n) if !n.is_empty() && n.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-') => n.to_string(),
            Some(n) => return error(422, "bad-name", &format!("'{n}': a name is lowercase letters, digits and -")),
            None => return error(422, "no-name", "POST needs a name"),
        },
        (_, Some(n)) => n.to_string(),
        _ => return error(405, "method", "this route takes GET and POST"),
    };
    let s = rules::subject(class, &name);
    let prior = match ctx.store.get(class, &name) { Ok(p) => p, Err(m) => return error(503, "store", &m) };
    let op = match method { "POST" => "create", "PUT" => "replace", "PATCH" => "patch", "DELETE" => "delete", _ => return error(405, "method", "unknown method") };
    if op == "create" && prior.is_some() { return error(409, "exists", &format!("{name} already exists; PATCH or PUT it")); }
    if op != "create" && prior.is_none() { return error(404, "not-found", &format!("no {} named {name}; a {op} never creates", class.name)); }
    if op != "create" {
        if let Err(r) = rules::may_write(class, prior.as_ref(), caller) { rules::event(&ctx.events, &caller.principal, op, class, &name, r.kind); return refused(r); }
    } else if let Err(r) = rules::may_write(class, Some(&json!({ "ownedBy": format!("principal-{}", caller.principal) }).as_object().cloned().unwrap_or_default()), caller) {
        return refused(r);
    }
    let mut cells = if op == "delete" { Vec::new() } else {
        match rules::cells(ctx.store, class, obj, op == "patch") { Ok(c) => c, Err(r) => { rules::event(&ctx.events, &caller.principal, op, class, &name, r.kind); return refused(r); } }
    };
    if op == "patch" && cells.is_empty() { return error(422, "empty-patch", "the patch names no field"); }
    if matches!(op, "create" | "replace") {
        if let Some(m) = rules::required_missing(class, &cells) { return error(422, "required", &format!("{m} is required")); }
        if rules::field(class, "ownedBy").is_some() {
            let owner = prior.as_ref().and_then(|r| r.get("ownedBy")).and_then(Value::as_str).map(String::from).unwrap_or_else(|| format!("principal-{}", caller.principal));
            cells.push(("ownedBy".into(), vec![rules::Cell::Link(format!("{}{owner}", model::NS))]));
        }
        if !cells.iter().any(|(k, _)| k == "label") { cells.push(("label".into(), vec![rules::Cell::Literal(name.clone(), "string")])); }
    }
    if let Some(p) = &prior {
        let n = match ctx.store.version_count(&format!("{}/{name}", class.plural)) { Ok(n) => n + 1, Err(m) => return error(503, "store", &m) };
        let (vs, vcells) = rules::version_row(class, &name, p, n);
        if let Err(m) = ctx.store.write(&format!("{}provenance", model::GRAPH_PREFIX), &vs, Some("Version"), &vcells, true) {
            return error(503, "store", &format!("could not keep the prior version, nothing written: {m}"));
        }
    }
    let result = match op {
        "delete" => ctx.store.delete(class.graph, &s),
        "create" => ctx.store.write(class.graph, &s, Some(class.name), &cells, false),
        "replace" => ctx.store.write(class.graph, &s, Some(class.name), &cells, true),
        _ => ctx.store.write(class.graph, &s, None, &cells, false),
    };
    if let Err(m) = result { rules::event(&ctx.events, &caller.principal, op, class, &name, "store-error"); return error(503, "store", &m); }
    rules::event(&ctx.events, &caller.principal, op, class, &name, "ok");
    let code = if op == "create" { 201 } else { 200 };
    (code, json!({ "status": "ok", "op": op, "name": name, "by": caller.principal }))
}

pub fn route(ctx: &Ctx, method: &str, url: &str, authorization: Option<&str>, body: &str) -> (u16, Value) {
    let (store, who) = (ctx.store, ctx.who);
    let (path, query) = url.split_once('?').unwrap_or((url, ""));
    if path == "/health" {
        return (200, json!({ "status": "ok", "product": PRODUCT, "productVersion": CRATE_VERSION, "apiVersion": API_VERSION }));
    }
    let parts: Vec<&str> = path.trim_matches('/').split('/').collect();
    // #4744 — the product root is its header, read under the same rule as every read
    if parts == [PRODUCT] && method == "GET" {
        if ctx.reads_public {
            return header(store, None);
        }
        return match who.caller(authorization) {
            Ok(c) => header(store, Some(&format!("{}principal-{}", model::NS, c.principal))),
            Err(e) => {
                let (code, kind) = auth::refusal(&e);
                error(code, kind, &format!("{e:?}"))
            }
        };
    }
    // #4744 — an operation (a live computation the model declares) answers under the same read rule
    if parts.len() >= 3 && parts[0] == PRODUCT && method == "GET" && ops::has(parts[1], parts[2]) {
        if !ctx.reads_public {
            if let Err(e) = who.caller(authorization) {
                let (code, kind) = auth::refusal(&e);
                return error(code, kind, &format!("{e:?}"));
            }
        }
        if let Some(r) = ops::route(ctx, parts[1], parts[2], &parts[3..], query) {
            return r;
        }
    }
    // #4742 (Jeff 10-25): the product is the top-level route, each of its domains a child route
    if parts.len() < 3 || parts[0] != PRODUCT {
        return error(404, "unknown-route", "not a route of this API");
    }
    let Some(class) = CLASSES.iter().find(|c| c.domain == parts[1] && c.segment == parts[2]) else {
        return error(404, "unknown-route", "no such collection in this product");
    };
    if method != "GET" {
        // every write names a signed caller first; nothing about the row is read before that
        let caller = match who.caller(authorization) {
            Ok(c) => c,
            Err(e) => {
                let (code, kind) = auth::refusal(&e);
                return error(code, kind, &format!("{e:?}"));
            }
        };
        let name = if parts.len() == 4 { Some(parts[3]) } else if parts.len() == 3 { None } else { return error(404, "unknown-route", "not a route of this API") };
        return write(ctx, &caller, method, class, name, body);
    }
    // #4524 — reads name their caller too, unless the product declares its data public:
    // a signed caller sees the rows it owns and the rows a Permission grants it, nothing else.
    let viewer = if ctx.reads_public {
        None
    } else {
        match who.caller(authorization) {
            Ok(c) => Some(format!("{}principal-{}", model::NS, c.principal)),
            Err(e) => {
                let (code, kind) = auth::refusal(&e);
                return error(code, kind, &format!("{e:?}"));
            }
        }
    };
    match parts.len() {
        3 => {
            let limit = query_param(query, "limit").unwrap_or(100).min(1000);
            let offset = query_param(query, "offset").unwrap_or(0);
            let w = match where_of(class, query) { Ok(w) => w, Err(e) => return e };
            let page = if w != store::Where::default() {
                store.list_where(class, limit, offset, viewer.as_deref(), &w)
            } else {
                match &viewer { Some(v) => store.list_seen_by(class, limit, offset, v), None => store.list(class, limit, offset) }
            };
            match page {
                Ok((rows, total)) => {
                    let mut e = envelope(class, path, json!(rows));
                    e["count"] = json!(total);
                    (200, e)
                }
                Err(m) => error(503, "store", &m),
            }
        }
        4 => match (match &viewer { Some(v) => store.get_seen_by(class, parts[3], v), None => store.get(class, parts[3]) }) {
            Ok(Some(row)) => (200, envelope(class, path, json!(row))),
            Ok(None) => error(404, "not-found", "no row with that name"),
            Err(m) => error(503, "store", &m),
        },
        _ => error(404, "unknown-route", "not a route of this API"),
    }
}

fn main() {
    let s = settings::load();
    // `<product>-api load <file.trig>`: fill the embedded store (a move from another
    // store, or a restore). `dump <file.trig>`: back it up. Both refuse a remote store.
    let args: Vec<String> = std::env::args().collect();
    if let (Some(cmd), Some(file)) = (args.get(1), args.get(2)) {
        if s.store_kind != "embedded" {
            eprintln!("{PRODUCT}-api {cmd}: store.kind is '{}', not embedded", s.store_kind);
            std::process::exit(2);
        }
        let e = store::Embedded::open(&s.store_path).unwrap_or_else(|m| { eprintln!("{m}"); std::process::exit(2) });
        let r = match cmd.as_str() {
            "load" => std::fs::read(file).map_err(|x| x.to_string()).and_then(|b| e.load_trig(&b)),
            "dump" => e.dump_trig().and_then(|b| std::fs::write(file, b).map_err(|x| x.to_string())),
            other => Err(format!("unknown command '{other}' (load | dump)")),
        };
        if let Err(m) = r { eprintln!("{PRODUCT}-api {cmd}: {m}"); std::process::exit(1); }
        eprintln!("{PRODUCT}-api {cmd} {file}: ok");
        return;
    }
    // #4524 — one engine for rows and for sign-in: an embedded product never reaches
    // for a remote store (or its credential) to learn who its people are.
    let engine = store::open_engine(&s);
    let store: Box<dyn store::RowStore> = Box::new(store::Sparql::shared(engine.clone()));
    // #4519 — the shared verifier reads THIS product's people (its namespace, its
    // identity graphs), never Chorus's; a verifier already set to another model is refused
    if let Err(m) = chorus_oidc::identity_model::configure(chorus_oidc::identity_model::IdentityModel::new(model::NS, &s.identity_graph_prefix)) {
        eprintln!("{PRODUCT}-api: {m}");
        std::process::exit(2);
    }
    let who = auth::build(&s.identity_issuer, move |q| engine.select_json(q).ok());
    let ctx = Ctx { store: store.as_ref(), who: &who, events: s.events_command.clone(), reads_public: s.reads_public };
    let server = match tiny_http::Server::http(&s.bind) {
        Ok(sv) => sv,
        Err(e) => {
            eprintln!("{PRODUCT}-api: cannot bind {}: {e}", s.bind);
            std::process::exit(2);
        }
    };
    eprintln!("{PRODUCT}-api {CRATE_VERSION} serving {} classes on {}", CLASSES.len(), s.bind);
    for mut req in server.incoming_requests() {
        let mut body = String::new();
        let _ = std::io::Read::take(req.as_reader(), 1 << 20).read_to_string(&mut body);
        let authorization = req.headers().iter().find(|h| h.field.equiv("Authorization")).map(|h| h.value.as_str().to_string());
        let (code, out) = route(&ctx, req.method().as_str(), req.url(), authorization.as_deref(), &body);
        let header = tiny_http::Header::from_bytes(&b"Content-Type"[..], &b"application/json"[..]).expect("static header");
        let resp = tiny_http::Response::from_string(out.to_string()).with_status_code(code).with_header(header);
        let _ = req.respond(resp);
    }
}
